insert into public.quiz_questions
  (category, difficulty, question_text, choices, correct_index, explanation_text, related_ingredient_id)
values
  ('nutrition', 'easy', '人参{にんじん}の 綺麗{きれい}な オレンジ色{いろ}の 元{もと}に なっている 栄養{えいよう}は?', '["カロテン","たんぱくしつ","カルシウム"]'::jsonb, 0, 'カロテンは 体{からだ}の 中{なか}で ビタミンAに 変{か}わって、目{め}や 肌{はだ}を 守{まも}って くれるよ。油{あぶら}と 一緒{いっしょ}に 食{た}べると もっと 体{からだ}に 取{と}り込{こ}まれやすく なるんだ。', (select im.id from public.ingredients_master im where im.name = '人参' limit 1)),
  ('nutrition', 'easy', '牛乳{ぎゅうにゅう}に たくさん 含{ふく}まれていて、骨{ほね}や 歯{は}を 丈夫{じょうぶ}に する 栄養{えいよう}は?', '["ビタミンC","カルシウム","鉄分{てつぶん}"]'::jsonb, 1, 'カルシウムは 骨{ほね}や 歯{は}を 作{つく}る もとに なる 栄養{えいよう}だよ。体{からだ}が 大{おお}きく 育{そだ}つ 子{こ}どもの 時期{じき}に とくに 大切{たいせつ}。', (select im.id from public.ingredients_master im where im.name = '牛乳' limit 1)),
  ('nutrition', 'easy', '豆腐{とうふ}や 納豆{なっとう}の 元{もと}の 大豆{だいず}は「畑{はたけ}の 肉{にく}」と 呼{よ}ばれる。それは 何{なに}が 多{おお}いから?', '["砂糖{さとう}","ビタミンC","たんぱくしつ"]'::jsonb, 2, '大豆{だいず}には 肉{にく}や 魚{さかな}に 負{ま}けない くらい たんぱくしつが 多{おお}く 入{はい}っているよ。たんぱくしつは 体{からだ}を 作{つく}る もとに なるよ。', (select im.id from public.ingredients_master im where im.name = '木綿豆腐' limit 1)),
  ('nutrition', 'normal', 'レモンに たくさん 含{ふく}まれている ビタミンは?', '["ビタミンD","ビタミンC","ビタミンK","ビタミンB12"]'::jsonb, 1, 'ビタミンCは 肌{はだ}を 作{つく}る コラーゲンの もとに なったり、かぜに まけない 体{からだ}づくりを 助{たす}けたり するよ。熱{ねつ}に 弱{よわ}いから 生{なま}で 食{た}べるのが おすすめ。', (select im.id from public.ingredients_master im where im.name = 'レモン' limit 1)),
  ('nutrition', 'normal', '納豆{なっとう}に 多{おお}く 含{ふく}まれ、骨{ほね}の 健康{けんこう}にも かかわる ビタミンは?', '["ビタミンA","ビタミンC","ビタミンK","ビタミンB1"]'::jsonb, 2, 'ビタミンKは けがを した ときに 血{ち}を 止{と}める 働{はたら}きや、カルシウムを 骨{ほね}に くっつける 働{はたら}きが あるよ。', (select im.id from public.ingredients_master im where im.name = '納豆' limit 1)),
  ('nutrition', 'normal', 'ほうれん草{そう}に 多{おお}く 含{ふく}まれ、貧血{ひんけつ}の 予防{よぼう}に 役立{やくだ}つ 栄養{えいよう}は?', '["ヨウ素{そ}","ナトリウム","ビタミンD","鉄{てつ}"]'::jsonb, 3, '血{ち}を 作{つく}る もとに なる 鉄{てつ}が 多{おお}い 野菜{やさい}だよ。ビタミンCと 一緒{いっしょ}に 食{た}べると もっと 体{からだ}に 取{と}り込{こ}まれやすく なるよ。', (select im.id from public.ingredients_master im where im.name = 'ほうれん草' limit 1)),
  ('nutrition', 'normal', 'トマトの 赤{あか}い 色{いろ}の 元{もと}に なっている 成分{せいぶん}は?', '["クロロフィル","リコピン","アントシアニン","イソフラボン"]'::jsonb, 1, 'リコピンは 体{からだ}の さびを ふせぐと いわれる 赤{あか}い 色素{しきそ}だよ。油{あぶら}と 一緒{いっしょ}に 食{た}べたり、煮{に}たり しても なくならないよ。', (select im.id from public.ingredients_master im where im.name = 'トマト' limit 1)),
  ('nutrition', 'normal', 'バナナに 多{おお}く 含{ふく}まれ、塩分{えんぶん}を 体{からだ}の 外{そと}に 出{だ}すのを 助{たす}ける ミネラルは?', '["カリウム","リン","マグネシウム","カルシウム"]'::jsonb, 0, 'カリウムは とりすぎた 塩分{えんぶん}を おしっこと 一緒{いっしょ}に 出{だ}すのを 助{たす}けて くれるよ。むくみが 気{き}に なる ときにも いいよ。', (select im.id from public.ingredients_master im where im.name = 'バナナ' limit 1)),
  ('nutrition', 'normal', 'にんにくの 独特{どくとく}の 匂{にお}いの 元{もと}に なる 成分{せいぶん}は?', '["リコピン","ヤラピン","アリシン","ムチン"]'::jsonb, 2, 'にんにくを 切{き}ったり すりおろしたり すると アリシンと いう 成分{せいぶん}が できて、あの 匂{にお}いに なるよ。ビタミンB1の 吸収{きゅうしゅう}を 助{たす}ける とも いわれるよ。', (select im.id from public.ingredients_master im where im.name = 'にんにく' limit 1)),
  ('nutrition', 'normal', 'サーモンの 身{み}の ピンク色{いろ}の 元{もと}で、海老{えび}や 蟹{かに}の 赤{あか}い 色{いろ}と 同{おな}じ 色素{しきそ}は?', '["カロテン","ルテイン","アスタキサンチン","クルクミン"]'::jsonb, 2, 'サーモンは もともと 白身{しろみ}の 魚{さかな}だけど、食{た}べている オキアミなどに 含{ふく}まれる アスタキサンチンが 体{からだ}に たまって ピンク色{いろ}に なるよ。', (select im.id from public.ingredients_master im where im.name = 'サーモン' limit 1)),
  ('nutrition', 'normal', '大豆{だいず}に 含{ふく}まれ、女性{じょせい}ホルモンに 似{に}た 働{はたら}きを すると いわれる 成分{せいぶん}は?', '["リコピン","イソフラボン","タウリン","カプサイシン"]'::jsonb, 1, '納豆{なっとう}や 豆腐{とうふ}などの 大豆{だいず}の 食{た}べ物{もの}に 多{おお}く 含{ふく}まれるよ。骨{ほね}の 健康{けんこう}にも かかわると いわれているよ。', (select im.id from public.ingredients_master im where im.name = '納豆' limit 1)),
  ('nutrition', 'normal', 'うなぎに とくに 多{おお}く、目{め}や 肌{はだ}・喉{のど}の 健康{けんこう}を 守{まも}る ビタミンは?', '["ビタミンB6","ビタミンK","ビタミンA","ビタミンC"]'::jsonb, 2, 'うなぎの 蒲焼{かばや}きは ビタミンAが とても 多{おお}い 食{た}べ物{もの}の ひとつだよ。ビタミンEや ビタミンB群{ぐん}も 含{ふく}まれているよ。', (select im.id from public.ingredients_master im where im.name = 'うなぎ' limit 1)),
  ('nutrition', 'normal', '「森{もり}の バター」と 呼{よ}ばれる アボカドに 多{おお}く 含{ふく}まれている 栄養{えいよう}は?', '["でんぷん","脂肪{しぼう}","ビタミンC","雑穀{ざっこく}"]'::jsonb, 1, '果物{くだもの}の 中{なか}では めずらしく、体{からだ}に よいと いわれる 脂肪{しぼう}(オレイン酸{さん}など)が 多{おお}く 含{ふく}まれているよ。', (select im.id from public.ingredients_master im where im.name = 'アボカド' limit 1)),
  ('nutrition', 'normal', '乾燥{かんそう}ひじきに 多{おお}く 含{ふく}まれ、骨{ほね}や 歯{は}を 作{つく}る 元{もと}に なる ミネラルは?', '["ヨウ素{そ}","リン","ナトリウム","カルシウム"]'::jsonb, 3, 'ひじきは 海{うみ}の 野菜{やさい}の 中{なか}でも カルシウムが とても 多{おお}いよ。食物繊維{しょくもつせんい}や 鉄{てつ}も 含{ふく}まれているよ。', (select im.id from public.ingredients_master im where im.name = '乾燥ひじき' limit 1)),
  ('nutrition', 'hard', '生{なま}の 生姜{しょうが}に 多{おお}い 辛味{からみ}成分{せいぶん} ジンゲロールは、加熱{かねつ}・乾燥{かんそう}すると 別{べつ}の 成分{せいぶん}に 変{か}わり、体{からだ}を 温{あたた}める 働{はたら}きが 強{つよ}まると いわれる。その 成分{せいぶん}は?', '["ショウガオール","ピペリン","アリシン","カプサイシン"]'::jsonb, 0, '生姜{しょうが}を 加熱{かねつ}したり 乾{ほ}したり すると 増{ふ}える 成分{せいぶん}だよ。生姜湯{しょうがゆ}や 煮物{にもの}に すると 体{からだ}が ぽかぽかに なりやすいよ。', (select im.id from public.ingredients_master im where im.name = 'しょうが' limit 1)),
  ('nutrition', 'hard', '「海{うみ}の ミルク」と 呼{よ}ばれる 牡蠣{かき}に とくに 多{おお}い ミネラルは?', '["ヨウ素{そ}","亜鉛{あえん}","フッ素{そ}","カリウム"]'::jsonb, 1, '亜鉛{あえん}は 味{あじ}を 感{かん}じる 細胞{さいぼう}や、体{からだ}を 作{つく}る たんぱくしつに かかわる ミネラルだよ。牡蠣{かき}は 食{た}べ物{もの}の 中{なか}でも とくに 多{おお}く 含{ふく}むよ。', (select im.id from public.ingredients_master im where im.name = '牡蠣' limit 1)),
  ('nutrition', 'hard', 'あさり などの 貝類{かいるい}に とくに 多{おお}い ビタミンは?', '["ビタミンE","ビタミンC","ビタミンB12","ビタミンK"]'::jsonb, 2, 'ビタミンB12は 血{ち}を 作{つく}るのを 助{たす}けて、貧血{ひんけつ}の 予防{よぼう}に 役立{やくだ}つよ。あさりは 鉄{てつ}も 多{おお}いから、貧血{ひんけつ}が 気{き}に なる ときに おすすめだよ。', (select im.id from public.ingredients_master im where im.name = 'あさり' limit 1)),
  ('nutrition', 'hard', '薩摩芋{さつまいも}を 切{き}った ときに 出{で}る 白{しろ}い 液体{えきたい}に 含{ふく}まれ、お腹{なか}の 調子{ちょうし}を 整{ととの}えると いわれる 成分{せいぶん}は?', '["アリシン","リコピン","カプサイシン","ヤラピン"]'::jsonb, 3, 'ヤラピンと いう 成分{せいぶん}だよ。食物繊維{しょくもつせんい}と 一緒{いっしょ}に お腹{なか}の 調子{ちょうし}を 整{ととの}える 助{たす}けに なると いわれているよ。', (select im.id from public.ingredients_master im where im.name = 'さつまいも' limit 1)),
  ('nutrition', 'hard', '卵{たまご}は「ほとんどの 栄養{えいよう}が 揃{そろ}っている」と いわれるが、ほとんど 含{ふく}まれていない 栄養素{えいようそ}は?', '["ビタミンC","ビタミンD","たんぱく質{しつ}","鉄{てつ}"]'::jsonb, 0, '卵{たまご}には ビタミンCと 食物繊維{しょくもつせんい}が ほとんど 入{はい}っていないよ。だから 野菜{やさい}や 果物{くだもの}と 一緒{いっしょ}に 食{た}べると バランスが よく なるよ。', (select im.id from public.ingredients_master im where im.name = '卵' limit 1)),
  ('season', 'easy', '次{つぎ}の うち、「夏{なつ}」が 旬{しゅん}の 野菜{やさい}は どれ?', '["ほうれんそう","胡瓜{きゅうり}","白菜{はくさい}"]'::jsonb, 1, '胡瓜{きゅうり}は 6月{がつ}から 8月{がつ}ごろが 旬{しゅん}だよ。水分{すいぶん}たっぷりで、暑{あつ}い 体{からだ}を 冷{ひ}やして くれるよ。', (select im.id from public.ingredients_master im where im.name = 'きゅうり' limit 1)),
  ('season', 'easy', '鍋料理{なべりょうり}に よく 使{つか}う、「冬{ふゆ}」が 旬{しゅん}の 野菜{やさい}は?', '["ゴーヤー","白菜{はくさい}","ズッキーニ"]'::jsonb, 1, '白菜{はくさい}は 11月{がつ}から 2月{がつ}ごろの 寒{さむ}い 時期{じき}が 旬{しゅん}だよ。寒{さむ}さに 当{あ}たると 甘{あま}みが 増{ま}すよ。', (select im.id from public.ingredients_master im where im.name = '白菜' limit 1)),
  ('season', 'easy', '「秋{あき}の 味覚{みかく}」と 呼{よ}ばれる 魚{さかな}は?', '["ふぐ","初鰹{はつがつお}","秋刀魚{さんま}"]'::jsonb, 2, '秋刀魚{さんま}は 9月{がつ}から 10月{がつ}ごろが 旬{しゅん}だよ。「秋{あき}の 刀{かたな}の 魚{さかな}」と 書{か}くのは、刀{かたな}の ような 形{かたち}を しているからだよ。', (select im.id from public.ingredients_master im where im.name = 'サンマ' limit 1)),
  ('season', 'easy', '桜桃{さくらんぼ}が 美味{おい}しい 季節{きせつ}は いつごろ?', '["春{はる}(3〜4月{がつ})","夏{なつ}の はじめ(6〜7月{がつ})","秋{あき}(10〜11月{がつ})"]'::jsonb, 1, '6月{がつ}から 7月{がつ}ごろが 旬{しゅん}だよ。傷{いた}みやすいから、この 時期{じき}だけの 楽{たの}しみだよ。', (select im.id from public.ingredients_master im where im.name = 'さくらんぼ' limit 1)),
  ('season', 'easy', '秋{あき}に 食{た}べる、いい匂{にお}いで 高級{こうきゅう}な きのこと いえば?', '["松茸{まつたけ}","もやし","榎茸{えのきたけ}"]'::jsonb, 0, '松茸{まつたけ}は 9月{がつ}から 10月{がつ}ごろの 秋{あき}が 旬{しゅん}だよ。「香{かお}り 松茸{まつたけ}」と 言{い}われる ほど 香{かお}りが 自慢{じまん}だよ。', (select im.id from public.ingredients_master im where im.name = '松茸' limit 1)),
  ('season', 'easy', '新{あたら}しい お米{こめ}「新米{しんまい}」が 出回{でまわ}るのは いつごろ?', '["春{はる}","夏{なつ}","秋{あき}","冬{ふゆ}"]'::jsonb, 2, 'お米{こめ}は 秋{あき}に 収穫{しゅうかく}するよ。とれたての 新米{しんまい}は 水分{すいぶん}たっぷりで、つやと 甘{あま}みが あるよ。', (select im.id from public.ingredients_master im where im.name = '米' limit 1)),
  ('season', 'normal', '「初鰹{はつがつお}」が 美味{おい}しいと いわれるのは、いつごろ?', '["5月{がつ}ごろ(春{はる}〜初夏{しょか})","1月{がつ}ごろ(冬{ふゆ})","10月{がつ}ごろ(秋{あき})","8月{がつ}ごろ(真夏{まなつ})"]'::jsonb, 0, '春{はる}から 初夏{しょか}に かけて 黒潮{くろしお}に 乗{の}って 北{きた}へ 進{すす}む 鰹{かつお}を「初鰹{はつがつお}」と 呼{よ}ぶよ。あっさりした 味{あじ}が 特徴{とくちょう}だよ。秋{あき}に 南{みなみ}へ 戻{もど}る「戻{もど}り鰹{がつお}」は 脂{あぶら}が のっているよ。', (select im.id from public.ingredients_master im where im.name = '初ガツオ' limit 1)),
  ('season', 'normal', '「筍{たけのこ}」と いう 漢字{かんじ}は、「竹{たけ}」と ある 漢字{かんじ}を 合{あ}わせて できている。その 漢字{かんじ}は?', '["句{く}","旬{しゅん}","匂{にお}い","勺{しゃく}"]'::jsonb, 1, '筍{たけのこ}は 10日{か}ほど(一旬{いちじゅん})で 竹{たけ}に なる ほど 成長{せいちょう}が 早{はや}いと いわれて、この 漢字{かんじ}が 使{つか}われているよ。旬{しゅん}は 3月{がつ}から 5月{がつ}ごろの 春{はる}だよ。', (select im.id from public.ingredients_master im where im.name = '筍' limit 1)),
  ('season', 'normal', '牡蠣{かき}は「Rの つく 月{つき}が 食{た}べごろ」と いわれる。Rが つくのは 英語{えいご}で 何月{なんがつ}から 何月{なんがつ}?', '["5月{がつ}〜8月{がつ}","6月{がつ}〜9月{がつ}","9月{がつ}〜4月{がつ}","12月{がつ}〜3月{がつ}だけ"]'::jsonb, 2, '英語{えいご}の 月{つき}の 名前{なまえ}に「R」が つく 時期{じき}が 食{た}べごろと いわれてきたよ。日本{にほん}では とくに 冬{ふゆ}の 牡蠣{かき}が おいしいよ。', (select im.id from public.ingredients_master im where im.name = '牡蠣' limit 1)),
  ('season', 'normal', '冬{ふゆ}の ほうれん草{そう}が 甘{あま}い のは、寒{さむ}さに 当{あ}たると 凍{こお}りにくい ように 何{なに}を 増{ふ}やすから?', '["ビタミンD","塩分{えんぶん}","たんぱく質{しつ}","糖分{とうぶん}"]'::jsonb, 3, '寒{さむ}さに 当{あ}たると、体{からだ}の 中{なか}の 水分{すいぶん}が 凍{こお}らない ように 糖分{とうぶん}を ためこむよ。だから 冬{ふゆ}の ほうれん草{そう}は 甘{あま}く なるよ。', (select im.id from public.ingredients_master im where im.name = 'ほうれん草' limit 1)),
  ('season', 'normal', '冬至{とうじ}(12月{がつ}ごろ)に 食{た}べると 風邪{かぜ}を ひかないと いわれる 野菜{やさい}は?', '["南瓜{かぼちゃ}","胡瓜{きゅうり}","ゴーヤー","ズッキーニ"]'::jsonb, 0, '南瓜{かぼちゃ}は 夏{なつ}から 秋{あき}に とれて、長{なが}く 保存{ほぞん}できるよ。野菜{やさい}が 少{すく}ない 冬{ふゆ}に 栄養{えいよう}を とる ための 昔{むかし}からの 知恵{ちえ}だよ。', (select im.id from public.ingredients_master im where im.name = 'かぼちゃ' limit 1)),
  ('season', 'normal', '夏{なつ}の「土用{どよう}の 丑{うし}の 日{ひ}」に 食{た}べる 習慣{しゅうかん}が ある 魚{さかな}は?', '["鰤{ぶり}","うなぎ","秋刀魚{さんま}","ふぐ"]'::jsonb, 1, '夏{なつ}バテを ふせぐ スタミナ源{げん}として 広{ひろ}まったよ。うなぎ 本来{ほんらい}の 旬{しゅん}は 秋{あき}から 冬{ふゆ}と いわれているよ。', (select im.id from public.ingredients_master im where im.name = 'うなぎ' limit 1)),
  ('origin', 'easy', 'みかんの 収穫量{しゅうかくりょう}が 日本一{にほんいち}の 県{けん}は?(2位{い}は 愛媛県{えひめけん}、3位{い}は 静岡県{しずおかけん})', '["長野県{ながのけん}","北海道{ほっかいどう}","和歌山県{わかやまけん}","沖縄県{おきなわけん}"]'::jsonb, 2, '和歌山県{わかやまけん}は 日本一{にほんいち}の みかんの 産地{さんち}だよ。あたたかい 気候{きこう}と、水{みず}はけの よい 山{やま}の 斜面{しゃめん}が みかん作{づく}りに 向{む}いているよ。', (select im.id from public.ingredients_master im where im.name = 'みかん' limit 1)),
  ('origin', 'easy', '国産{こくさん}の 桜桃{さくらんぼ}の 収穫量{しゅうかくりょう}が 日本一{にほんいち}の 県{けん}は?', '["高知県{こうちけん}","青森県{あおもりけん}","沖縄県{おきなわけん}","山形県{やまがたけん}"]'::jsonb, 3, '山形県{やまがたけん}は 国内{こくない}の 生産量{せいさんりょう}の およそ 7割{わり}を 占{し}める 大産地{だいさんち}だよ。「佐藤錦{さとうにしき}」が とくに 有名{ゆうめい}だよ。', (select im.id from public.ingredients_master im where im.name = 'さくらんぼ' limit 1)),
  ('origin', 'easy', 'ゴーヤーの 収穫量{しゅうかくりょう}が 日本一{にほんいち}の 県{けん}は?', '["沖縄県{おきなわけん}","青森県{あおもりけん}","北海道{ほっかいどう}","岩手県{いわてけん}"]'::jsonb, 0, 'ゴーヤーは 沖縄{おきなわ}の 夏{なつ}を 代表{だいひょう}する 野菜{やさい}だよ。暑{あつ}い 夏{なつ}を 乗{の}り切{き}る ための 食{た}べ物{もの}として 昔{むかし}から 食{た}べられて きたよ。', (select im.id from public.ingredients_master im where im.name = 'ゴーヤー' limit 1)),
  ('origin', 'easy', 'トマトの ふるさと(原産地{げんさんち})は どこ?', '["オーストラリア","南米{なんべい}(アンデス高原{こうげん})","北{きた}ヨーロッパ","日本{にほん}"]'::jsonb, 1, 'トマトは 南米{なんべい}の アンデス高原{こうげん}が ふるさとだよ。ヨーロッパに 伝{つた}わった ころは 観賞用{かんしょうよう}で、あとから 食{た}べられるように なったよ。', (select im.id from public.ingredients_master im where im.name = 'トマト' limit 1)),
  ('origin', 'easy', 'キムチは どこの 国{くに}の 漬物{つけもの}が 元{もと}に なっている?', '["メキシコ","タイ","韓国{かんこく}","フランス"]'::jsonb, 2, '韓国{かんこく}の 漬物{つけもの}だよ。白菜{はくさい}や 大根{だいこん}を 唐辛子{とうがらし}や にんにくなどと 一緒{いっしょ}に 発酵{はっこう}させて 作{つく}るよ。', (select im.id from public.ingredients_master im where im.name = 'キムチ' limit 1)),
  ('origin', 'easy', '「生春巻{なまはるま}き」の 皮{かわ}に 使{つか}う ライスペーパーで 有名{ゆうめい}な 国{くに}は?', '["ドイツ","ブラジル","ロシア","ベトナム"]'::jsonb, 3, 'お米{こめ}の 粉{こな}を 薄{うす}く 伸{の}ばして 乾{かわ}かした もので、ベトナム料理{りょうり}の 定番{ていばん}だよ。', (select im.id from public.ingredients_master im where im.name = 'ライスペーパー' limit 1)),
  ('origin', 'normal', '日本{にほん}の じゃがいもの およそ どれくらいが 北海道{ほっかいどう}で 作{つく}られている?', '["およそ 8割{わり}","およそ 1割{わり}","およそ 5割{わり}","およそ 3割{わり}"]'::jsonb, 0, '広{ひろ}い 畑{はたけ}と 涼{すず}しい 気候{きこう}が じゃがいもに 向{む}いていて、日本{にほん}の 生産量{せいさんりょう}の およそ 8割{わり}を 占{し}めているよ。', (select im.id from public.ingredients_master im where im.name = 'じゃがいも' limit 1)),
  ('origin', 'normal', '「淡路島{あわじしま}」の 名産{めいさん}として 有名{ゆうめい}な 野菜{やさい}は?', '["ゴーヤー","玉葱{たまねぎ}","バジル","牛蒡{ごぼう}"]'::jsonb, 1, '兵庫県{ひょうごけん}の 淡路島{あわじしま}は、甘{あま}くて 柔{やわ}らかい「淡路島{あわじしま}たまねぎ」で 有名{ゆうめい}だよ。生{なま}でも 食{た}べやすいよ。', (select im.id from public.ingredients_master im where im.name = '玉ねぎ' limit 1)),
  ('origin', 'normal', '林檎{りんご}の 収穫量{しゅうかくりょう}が 日本一{にほんいち}の 県{けん}は?', '["岩手県{いわてけん}","長野県{ながのけん}","青森県{あおもりけん}","山形県{やまがたけん}"]'::jsonb, 2, '青森県{あおもりけん}は 国内{こくない}の およそ 6割{わり}を 占{し}める 大産地{だいさんち}だよ。2位{い}は 長野県{ながのけん}だよ。', (select im.id from public.ingredients_master im where im.name = 'りんご' limit 1)),
  ('origin', 'normal', '葡萄{ぶどう}の 収穫量{しゅうかくりょう}が 日本一{にほんいち}の 県{けん}は?', '["北海道{ほっかいどう}","福岡県{ふくおかけん}","岡山県{おかやまけん}","山梨県{やまなしけん}"]'::jsonb, 3, '山梨県{やまなしけん}は 豊{ゆた}かな 自然{しぜん}と 気候{きこう}を 活{い}かして、日本一{にほんいち}の 収穫量{しゅうかくりょう}を 誇{ほこ}っているよ。', null),
  ('origin', 'normal', '冬{ふゆ}の 味覚{みかく}「松葉蟹{まつばがに}」は、何{なに}ガニの 呼{よ}び名{な}?', '["ズワイガニ","ワタリガニ","タラバガニ","毛蟹{けがに}"]'::jsonb, 0, '山陰{さんいん}地方{ちほう}で とれる オスの ズワイガニに つけられた 呼{よ}び名{な}だよ。', (select im.id from public.ingredients_master im where im.name = 'ズワイガニ' limit 1)),
  ('origin', 'normal', 'イタリアの「パルマ」で 作{つく}られる ことで 有名{ゆうめい}な 高級{こうきゅう}食材{しょくざい}は?', '["バター","生{なま}ハム","ゴルゴンゾーラ","ソーセージ"]'::jsonb, 1, '塩{しお}と 時間{じかん}だけで 仕上{しあ}げる イタリアの 伝統的{でんとうてき}な ハムだよ。', (select im.id from public.ingredients_master im where im.name = '生ハム' limit 1)),
  ('origin', 'normal', '中国{ちゅうごく}の 楊貴妃{ようきひ}が 好{この}んだと 伝{つた}えられる フルーツは?', '["林檎{りんご}","桜桃{さくらんぼ}","ライチ","バナナ"]'::jsonb, 2, '楊貴妃{ようきひ}は ライチが 大好{だいす}きで、遠{とお}くの 産地{さんち}から 速{はや}い 馬{うま}で 運{はこ}ばせたと 伝{つた}えられているよ。', (select im.id from public.ingredients_master im where im.name = 'ライチ' limit 1)),
  ('origin', 'normal', 'ロシアや ウクライナの ボルシチの 赤{あか}い 色{いろ}を 作{つく}る 野菜{やさい}は?', '["人参{にんじん}","トマト","パプリカ","ビーツ"]'::jsonb, 3, 'ビーツは「食{た}べる 輸血{ゆけつ}」とも 呼{よ}ばれる ほど 赤紫色{あかむらさきいろ}が 鮮{あざ}やかな 根{ね}っこの 野菜{やさい}だよ。', (select im.id from public.ingredients_master im where im.name = 'ビーツ' limit 1)),
  ('origin', 'hard', '国産{こくさん}松茸{まつたけ}の 産地{さんち}として 有名{ゆうめい}で、収穫量{しゅうかくりょう}が 多{おお}い 県{けん}は?', '["長野県{ながのけん}","北海道{ほっかいどう}","千葉県{ちばけん}","沖縄県{おきなわけん}"]'::jsonb, 0, '赤松{あかまつ}の 林{はやし}に 生{は}える きのこで、長野県{ながのけん}は 国内{こくない}でも 有数{ゆうすう}の 産地{さんち}だよ。年{とし}によって 順位{じゅんい}が 変{か}わることも あるよ。', (select im.id from public.ingredients_master im where im.name = '松茸' limit 1)),
  ('origin', 'hard', '養殖{ようしょく}うなぎの 生産量{せいさんりょう}が 日本一{にほんいち}の 県{けん}は?', '["愛知県{あいちけん}","鹿児島県{かごしまけん}","静岡県{しずおかけん}","宮崎県{みやざきけん}"]'::jsonb, 1, '鹿児島県{かごしまけん}は 豊{ゆた}かな 地下水{ちかすい}と あたたかい 気候{きこう}を 活{い}かして、生産量{せいさんりょう}日本一{にほんいち}を 誇{ほこ}っているよ。', (select im.id from public.ingredients_master im where im.name = 'うなぎ' limit 1)),
  ('origin', 'hard', '山口県{やまぐちけん}の 下関{しものせき}では、ふぐを 別{べつ}の 名前{なまえ}で 呼{よ}ぶ。それは?', '["ぷく","ふぐー","ふく","ふうぐ"]'::jsonb, 2, '「ふぐ」が「不具{ふぐ}・不幸{ふこう}」に 聞{き}こえて 縁起{えんぎ}が 悪{わる}いと されるので、「福{ふく}」に かけて「ふく」と 呼{よ}ぶよ。', (select im.id from public.ingredients_master im where im.name = 'ふぐ' limit 1)),
  ('origin', 'hard', '本場{ほんば}イタリアの モッツァレラは 何{なに}の 乳{ちち}から 作{つく}られる?', '["馬{うま}","山羊{やぎ}","羊{ひつじ}","水牛{すいぎゅう}"]'::jsonb, 3, '本来{ほんらい}は 水牛{すいぎゅう}の 乳{ちち}から 作{つく}られ、濃厚{のうこう}な 味{あじ}わいが 特徴{とくちょう}だよ。日本{にほん}で よく 見{み}る ものは 牛乳{ぎゅうにゅう}から 作{つく}る ことが 多{おお}いよ。', (select im.id from public.ingredients_master im where im.name = 'モッツァレラチーズ' limit 1)),
  ('origin', 'normal', 'メキシコ料理{りょうり}の タコスの 皮{かわ}に 使{つか}う「トルティーヤ」の 伝統的{でんとうてき}な 原料{げんりょう}は?', '["とうもろこし","そば","じゃがいも","米{こめ}"]'::jsonb, 0, 'とうもろこしの 粉{こな}を 薄{うす}く 焼{や}いた ものが 伝統的{でんとうてき}な トルティーヤだよ。小麦粉{こむぎこ}で 作{つく}る ものも あるよ。', (select im.id from public.ingredients_master im where im.name = 'トルティーヤ' limit 1)),
  ('storage', 'easy', 'バナナを 美味{おい}しく 保存{ほぞん}するには?', '["冷蔵庫{れいぞうこ}の 野菜室{やさいしつ}","冷凍庫{れいとうこ}","風通{かぜとお}しの いい 常温{じょうおん}"]'::jsonb, 2, 'バナナは 寒{さむ}さが 苦手{にがて}で、冷蔵庫{れいぞうこ}に 入{い}れると 皮{かわ}が 黒{くろ}くなって しまうよ。風通{かぜとお}しの いい 常温{じょうおん}に 置{お}いてね。', (select im.id from public.ingredients_master im where im.name = 'バナナ' limit 1)),
  ('storage', 'normal', 'じゃがいもの 芽{め}や 緑色{みどりいろ}に なった 部分{ぶぶん}に 含{ふく}まれ、食{た}べすぎると 体{からだ}に よくない 成分{せいぶん}は?', '["ヤラピン","リコピン","ソラニン","アリシン"]'::jsonb, 2, '日光{にっこう}に 当{あ}たると 増{ふ}える 毒{どく}の 成分{せいぶん}だよ。芽{め}は 深{ふか}めに 取{と}り、緑色{みどりいろ}の 部分{ぶぶん}は 切{き}り落{お}として 食{た}べてね。', (select im.id from public.ingredients_master im where im.name = 'じゃがいも' limit 1)),
  ('storage', 'normal', '玉葱{たまねぎ}の 保存{ほぞん}に 向{む}いている 場所{ばしょ}は?', '["日当{ひあ}たりの よい 窓際{まどぎわ}","水{みず}を 張{は}った ボウルの 中{なか}","冷凍庫{れいとうこ}","風通{かぜとお}しの よい 涼{すず}しい 暗{くら}い ところ"]'::jsonb, 3, '玉葱{たまねぎ}は 湿気{しっけ}が 苦手{にがて}だから、ネットなどに 入{い}れて つるすなど、涼{すず}しくて 暗{くら}い ところで 保存{ほぞん}してね。', (select im.id from public.ingredients_master im where im.name = '玉ねぎ' limit 1)),
  ('storage', 'hard', '卵{たまご}を 保存{ほぞん}する とき、いいと いわれる 向{む}きは?', '["とがった 方{ほう}を 下{した}に する","横{よこ}に 寝{ね}かせる","向{む}きは 関係{かんけい}ない","丸{まる}い 方{ほう}を 下{した}に する"]'::jsonb, 0, '卵{たまご}の 丸{まる}い 方{ほう}には 空気{くうき}の 部屋{へや}が あるよ。とがった 方{ほう}を 下{した}に すると 黄身{きみ}が かたよりにくく なって、長持{ながも}ちしやすいと いわれているよ。', (select im.id from public.ingredients_master im where im.name = '卵' limit 1)),
  ('storage', 'normal', '葉{は}つきの 大根{だいこん}を 買{か}ってきた。保存{ほぞん}する 前{まえ}に すると よい ことは?', '["そのまま 冷凍庫{れいとうこ}に 入{い}れる","葉{は}を 切{き}り落{お}として 別{べつ}に 保存{ほぞん}する","皮{かわ}を 全部{ぜんぶ} むく","水{みず}に つけたまま 常温{じょうおん}に 置{お}く"]'::jsonb, 1, '葉{は}を つけた ままだと、葉{は}っぱが 大根{だいこん}の 水分{すいぶん}や 栄養{えいよう}を 吸{す}って しまうよ。葉{は}は 切{き}り離{はな}して 別{べつ}に 保存{ほぞん}してね。', (select im.id from public.ingredients_master im where im.name = '大根' limit 1)),
  ('storage', 'normal', '小松菜{こまつな}や ほうれん草{そう}などの 葉物{はもの}野菜{やさい}は、冷蔵庫{れいぞうこ}で どんな 向{む}きに 保存{ほぞん}すると 長持{ながも}ちする?', '["向{む}きは 関係{かんけい}ない","寝{ね}かせて 保存{ほぞん}する","立{た}てて 保存{ほぞん}する","逆{さか}さまに する"]'::jsonb, 2, '畑{はたけ}で 育{そだ}っていた 向{む}きに 合{あ}わせて 立{た}てて 保存{ほぞん}すると、野菜{やさい}が 疲{つか}れにくく 長持{ながも}ちするよ。', (select im.id from public.ingredients_master im where im.name = '小松菜' limit 1)),
  ('storage', 'normal', '夏{なつ}に お米{こめ}を 保存{ほぞん}する とき、虫{むし}や カビを 防{ふせ}ぐために おすすめの 場所{ばしょ}は?', '["日当{ひあ}たりの よい ベランダ","ガスコンロの となり","流{なが}しの 下{した}","冷蔵庫{れいぞうこ}の 野菜室{やさいしつ}"]'::jsonb, 3, 'お米{こめ}は 暑{あつ}さと 湿気{しっけ}が 苦手{にがて}だよ。ペットボトルなどに 入{い}れて、冷蔵庫{れいぞうこ}の 野菜室{やさいしつ}で 保存{ほぞん}すると 安心{あんしん}だよ。', (select im.id from public.ingredients_master im where im.name = '米' limit 1)),
  ('storage', 'normal', '生{なま}しいたけを 日光{にっこう}に 当{あ}てて 干{ほ}すと、増{ふ}える 栄養素{えいようそ}は?', '["ビタミンD","ビタミンC","ビタミンB12","ビタミンK"]'::jsonb, 0, 'しいたけには ビタミンDの もとに なる 成分{せいぶん}が 含{ふく}まれていて、日光{にっこう}に 当{あ}てると ビタミンDに 変{か}わるよ。干{ほ}すと 保存{ほぞん}も できて 一石二鳥{いっせきにちょう}だよ。', (select im.id from public.ingredients_master im where im.name = '生しいたけ' limit 1)),
  ('storage', 'normal', '硬{かた}い アボカドを 早{はや}く 熟{じゅく}させる 方法{ほうほう}は?', '["冷凍庫{れいとうこ}に 入{い}れる","林檎{りんご}と 一緒{いっしょ}に 紙袋{かみぶくろ}に 入{い}れる","冷蔵庫{れいぞうこ}に 入{い}れる","水{みず}に つける"]'::jsonb, 1, '林檎{りんご}から 出{で}る ガスが、アボカドが 熟{じゅく}すのを 早{はや}めて くれるよ。熟{じゅく}したら 冷蔵庫{れいぞうこ}に 移{うつ}してね。', (select im.id from public.ingredients_master im where im.name = 'アボカド' limit 1)),
  ('cooking', 'easy', '玉葱{たまねぎ}を 切{き}る とき 涙{なみだ}が 出{で}にくく なる 方法{ほうほう}は?', '["切{き}る 前{まえ}に 温{あたた}める","よく 日光{にっこう}に 当{あ}てる","切{き}る 前{まえ}に 冷{ひ}やす"]'::jsonb, 2, '冷{ひ}やして おくと、涙{なみだ}の 元{もと}に なる 成分{せいぶん}が 空気中{くうきちゅう}に 出{で}にくく なるよ。よく 切{き}れる 包丁{ほうちょう}を 使{つか}うのも コツだよ。', (select im.id from public.ingredients_master im where im.name = '玉ねぎ' limit 1)),
  ('cooking', 'easy', 'ブロッコリーは、何{なに}の つぼみを 食{た}べているの?', '["花{はな}の つぼみ","葉{は}の 先{さき}","根{ね}っこ"]'::jsonb, 0, '花{はな}が 咲{さ}く 前{まえ}の つぼみが たくさん 集{あつ}まった ものを 食{た}べているよ。茹{ゆ}ですぎずに 蒸{む}すと、栄養{えいよう}が 逃{に}げにくいよ。', (select im.id from public.ingredients_master im where im.name = 'ブロッコリー' limit 1)),
  ('cooking', 'normal', '胡瓜{きゅうり}を 塩{しお}で こすってから 使{つか}う 調理{ちょうり}を 何{なん}と いう?', '["板摺{いたず}り","削{そ}ぎ切{ぎ}り","下茹{したゆ}で","灰汁抜{あくぬ}き"]'::jsonb, 0, '板摺{いたず}りを すると 色{いろ}が 鮮{あざ}やかに なって、青臭{あおくさ}さが 抜{ぬ}けて、味{あじ}も しみこみやすく なるよ。', (select im.id from public.ingredients_master im where im.name = 'きゅうり' limit 1)),
  ('cooking', 'normal', 'あさりの 砂抜{すなぬ}きに 使{つか}う 塩水{しおみず}の 濃度{のうど}は、およそ 何{なん}%?', '["0.5%","3%","10%","20%"]'::jsonb, 1, '海水{かいすい}と 同{おな}じ くらいの 3%(お水{みず}500mLに 塩{しお} 大{おお}さじ1)が 目安{めやす}だよ。暗{くら}い ところに しばらく 置{お}いておくと 砂{すな}を 吐{は}いてくれるよ。', (select im.id from public.ingredients_master im where im.name = 'あさり' limit 1)),
  ('cooking', 'normal', '「木綿豆腐{もめんどうふ}」の 名前{なまえ}の 由来{ゆらい}は?', '["木綿{もめん}の 畑{はたけ}で 作{つく}るから","固{かた}める ときに 木綿{もめん}の 布{ぬの}を 敷{し}いた 型{かた}を 使{つか}うから","木綿{もめん}の 色{いろ}に 似{に}ているから","木綿{もめん}の 花{はな}から 作{つく}るから"]'::jsonb, 1, '水分{すいぶん}を しぼる ときに 布{ぬの}を 敷{し}いた 型{かた}に 入{い}れるから、表面{ひょうめん}に 布目{ぬのめ}が つくよ。絹{きぬ}ごし豆腐{どうふ}より 水分{すいぶん}が 少{すく}なく しっかりしているよ。', (select im.id from public.ingredients_master im where im.name = '木綿豆腐' limit 1)),
  ('cooking', 'easy', '半熟卵{はんじゅくたまご}を 作{つく}るには、沸騰{ふっとう}した お湯{ゆ}で およそ 何分{なんぷん} 茹{ゆ}でる?', '["1分{ぷん}","6〜7分{ぷん}","20分{ぷん}","30分{ぷん}"]'::jsonb, 1, '室温{しつおん}に 戻{もど}した 卵{たまご}を お湯{ゆ}に 入{い}れて、6〜7分{ぷん}で とろっとした 半熟{はんじゅく}に なるよ。10〜12分{ぷん}で かたゆでに なるよ。', (select im.id from public.ingredients_master im where im.name = '卵' limit 1)),
  ('cooking', 'hard', 'パスタを 茹{ゆ}でる お湯{ゆ}に 入{い}れる 塩{しお}は、お湯{ゆ}の およそ 何{なん}%?', '["0.1%","1%","5%","10%"]'::jsonb, 1, 'お湯{ゆ} 1Lに 塩{しお} 10gくらい、1%が 目安{めやす}だよ。パスタ自体{じたい}に うっすら 塩味{しおあじ}が ついて、ソースと なじみやすく なるよ。', (select im.id from public.ingredients_master im where im.name = 'パスタ' limit 1)),
  ('cooking', 'easy', 'こんにゃくの 元{もと}に なる 野菜{やさい}は?', '["こんにゃくいも","里芋{さといも}","じゃがいも"]'::jsonb, 0, 'こんにゃくいもを すりおろして、石灰{せっかい}などで 固{かた}めて 作{つく}るよ。ほとんどが 水分{すいぶん}と 食物繊維{しょくもつせんい}だよ。', (select im.id from public.ingredients_master im where im.name = 'こんにゃく' limit 1)),
  ('cooking', 'easy', '納豆{なっとう}は 何{なに}を 発酵{はっこう}させて 作{つく}る?', '["米{こめ}","大豆{だいず}","小麦{こむぎ}"]'::jsonb, 1, '茹{ゆ}でた 大豆{だいず}に 納豆菌{なっとうきん}を 加{くわ}えて 発酵{はっこう}させるよ。あの ねばねばは たんぱくしつが 分解{ぶんかい}されて できるよ。', (select im.id from public.ingredients_master im where im.name = '納豆' limit 1)),
  ('cooking', 'easy', 'ヨーグルトは、牛乳{ぎゅうにゅう}を 何{なに}の 働{はたら}きで 固{かた}めた もの?', '["酵母{こうぼ}","酢{す}","乳酸菌{にゅうさんきん}"]'::jsonb, 2, '乳酸菌{にゅうさんきん}が 牛乳{ぎゅうにゅう}の 糖分{とうぶん}を 分解{ぶんかい}して 乳酸{にゅうさん}を 作{つく}り、酸味{さんみ}が 出{で}て 固{かた}まるよ。', (select im.id from public.ingredients_master im where im.name = 'ヨーグルト' limit 1)),
  ('cooking', 'easy', 'お餅{もち}の 原料{げんりょう}は?', '["糯米{もちごめ}","小麦粉{こむぎこ}","粳米{うるちごめ}"]'::jsonb, 0, '糯米{もちごめ}を 蒸{む}して ついた ものだよ。ふだん ごはんに する お米{こめ}(粳米{うるちごめ})より、強{つよ}い ねばりが 出{で}るよ。', (select im.id from public.ingredients_master im where im.name = 'もち' limit 1)),
  ('cooking', 'easy', '蓮根{れんこん}に 穴{あな}が いくつも 開{あ}いているのは、何{なん}の ため?', '["水{みず}を 溜{た}める ため","空気{くうき}を 通{とお}す ため","虫{むし}が 入{はい}る ため"]'::jsonb, 1, '泥{どろ}の 中{なか}で 育{そだ}つ 蓮根{れんこん}は、葉{は}っぱから 根{ね}っこまで 空気{くうき}を 送{おく}る ための 通{とお}り道{みち}として 穴{あな}が 開{あ}いているよ。', (select im.id from public.ingredients_master im where im.name = 'れんこん' limit 1)),
  ('cooking', 'normal', 'ピーマンの 苦{にが}みを 抑{おさ}えやすい 切{き}り方{かた}は?', '["ミキサーに かける","水{みず}に 半日{はんにち} つける","繊維{せんい}を 断{た}つ ように 横{よこ}に 切{き}る","繊維{せんい}に 沿{そ}って 縦{たて}に 切{き}る"]'::jsonb, 3, '繊維{せんい}を こわさない ように 縦{たて}に 切{き}ると、苦{にが}みや 水分{すいぶん}が 出{で}にくいよ。', (select im.id from public.ingredients_master im where im.name = 'ピーマン' limit 1)),
  ('cooking', 'normal', '「香{かお}り 松茸{まつたけ}、味{あじ} ○○」の ○○に 入{はい}る きのこは?', '["しめじ","舞茸{まいたけ}","椎茸{しいたけ}","榎{えのき}"]'::jsonb, 0, '松茸{まつたけ}の 香{かお}りと、しめじの 味{あじ}の よさを たたえた 日本{にほん}の ことわざだよ。', (select im.id from public.ingredients_master im where im.name = 'しめじ' limit 1)),
  ('cooking', 'normal', '本鮪{ほんまぐろ}の「大{だい}トロ」は、体{からだ}の どの 部分{ぶぶん}の 身{み}?', '["尻尾{しっぽ}","腹側{はらがわ}","背側{せながわ}","頭{あたま}"]'::jsonb, 1, '脂{あぶら}が いちばん たくさん のっている お腹{なか}側{がわ}の 身{み}だよ。背中{せなか}側{がわ}は「赤身{あかみ}」に なるよ。', (select im.id from public.ingredients_master im where im.name = '本マグロ（大トロ）' limit 1)),
  ('cooking', 'easy', 'ホタテの 貝柱{かいばしら}は、貝殻{かいがら}を どうする 筋肉{きんにく}?', '["閉{と}じる","延{の}ばす","踊{おど}る"]'::jsonb, 0, '貝殻{かいがら}を ぎゅっと 閉{と}じる ための 筋肉{きんにく}だよ。ホタテは この 貝柱{かいばしら}を 動{うご}かして 泳{およ}ぐ こともできるよ。', (select im.id from public.ingredients_master im where im.name = 'ホタテ' limit 1)),
  ('cooking', 'normal', '小骨{こぼね}の 多{おお}い ハモを 食{た}べやすく する、包丁{ほうちょう}で 細{こま}かく 切{き}れ目{め}を 入{い}れる 下拵{したごしら}えは?', '["骨切{ほねき}り","隠{かく}し包丁{ぼうちょう}","板摺{いたず}り","湯剥{ゆむ}き"]'::jsonb, 0, '1寸{すん}(約{やく}3cm)に 24本{ほん}ほど 包丁{ほうちょう}を 入{い}れる 技{わざ}だよ。小骨{こぼね}が 多{おお}い ハモを 美味{おい}しく 食{た}べる ための 工夫{くふう}だよ。', (select im.id from public.ingredients_master im where im.name = 'ハモ' limit 1)),
  ('cooking', 'hard', 'ふぐの 毒{どく}の 名前{なまえ}は?', '["アリシン","テトロドトキシン","ムチン","ソラニン"]'::jsonb, 1, '肝臓{かんぞう}や 卵巣{らんそう}などに 含{ふく}まれる 強{つよ}い 毒{どく}だよ。ふぐを さばくには 専門{せんもん}の 免許{めんきょ}が いるよ。', (select im.id from public.ingredients_master im where im.name = 'ふぐ' limit 1)),
  ('cooking', 'hard', '「喉黒{のどぐろ}」と 呼{よ}ばれる 高級魚{こうきゅうぎょ}の 正式{せいしき}な 和名{わめい}は?', '["ホッケ","金目鯛{きんめだい}","赤鯥{あかむつ}","目張{めばる}"]'::jsonb, 2, '口{くち}の 中{なか}が 黒{くろ}い ことから のどぐろと 呼{よ}ばれているよ。正式{せいしき}な 名前{なまえ}は 赤鯥{あかむつ}だよ。', (select im.id from public.ingredients_master im where im.name = 'のどぐろ' limit 1)),
  ('cooking', 'easy', 'マルゲリータ ピザの 赤{あか}・白{しろ}・緑{みどり}の うち、緑{みどり}は どの 食材{しょくざい}?', '["ほうれん草{そう}","バジル","ピーマン"]'::jsonb, 1, 'トマトの 赤{あか}、モッツァレラの 白{しろ}、バジルの 緑{みどり}で イタリアの 国旗{こっき}を 表{あらわ}しているよ。', (select im.id from public.ingredients_master im where im.name = 'バジル' limit 1)),
  ('cooking', 'normal', 'ホワイトアスパラガスが 白{しろ}いのは どうして?', '["日光{にっこう}に 当{あ}てず 土{つち}を かぶせて 育{そだ}てるから","品種{ひんしゅ}が 全{まった}く 違{ちが}うから","白{しろ}い 肥料{ひりょう}を 使{つか}うから","収穫後{しゅうかくご}に 漂白{ひょうはく}するから"]'::jsonb, 0, '日光{にっこう}に 当{あ}てない ように 土{つち}を かぶせて 育{そだ}てると、緑色{みどりいろ}の 元{もと}が できずに 白{しろ}く なるよ。緑{みどり}の アスパラガスと 同{おな}じ 種類{しゅるい}の 野菜{やさい}だよ。', (select im.id from public.ingredients_master im where im.name = '初物アスパラガス' limit 1)),
  ('cooking', 'normal', 'ズッキーニは 何{なに}の 仲間{なかま}?', '["南瓜{かぼちゃ}","胡瓜{きゅうり}","茄子{なす}","ピーマン"]'::jsonb, 0, '見{み}た目{め}は 胡瓜{きゅうり}に 似{に}ているけど、南瓜{かぼちゃ}の 仲間{なかま}の 野菜{やさい}だよ。花{はな}も 食{た}べられるよ。', (select im.id from public.ingredients_master im where im.name = 'ズッキーニ' limit 1)),
  ('cooking', 'normal', 'パクチーの 英語{えいご}の 名前(ほかの 呼{よ}び名{な})は?', '["ディル","バジル","コリアンダー","ミント"]'::jsonb, 2, 'タイ語{ご}で パクチー、英語{えいご}では コリアンダーと 呼{よ}ばれるよ。独特{どくとく}の 香{かお}りが 特徴{とくちょう}だよ。', (select im.id from public.ingredients_master im where im.name = 'パクチー' limit 1)),
  ('cooking', 'hard', '高級{こうきゅう}食材{しょくざい}の トリュフは「黒{くろ}い ○○」と 呼{よ}ばれる。○○に 入{はい}る 言葉{ことば}は?', '["黄金{おうごん}","宝石箱{ほうせきばこ}","真珠{しんじゅ}","ダイヤ"]'::jsonb, 3, '珍{めずら}しくて 高価{こうか}な ことから 黒{くろ}い トリュフは「黒{くろ}い ダイヤ」と 呼{よ}ばれているよ。地面{じめん}の 中{なか}で 育{そだ}つ きのこだよ。', (select im.id from public.ingredients_master im where im.name = 'トリュフ' limit 1)),
  ('cooking', 'hard', 'オリーブオイルの「エクストラバージン」とは、どんな 油{あぶら}?', '["実{み}を 絞{しぼ}った ままの、いちばん 品質{ひんしつ}の 高{たか}い 油{あぶら}","古{ふる}い 実{み}から 取{と}った 油{あぶら}","何度{なんど}も 精製{せいせい}した 安{やす}い 油{あぶら}","オリーブ 以外{いがい}を 混{ま}ぜた 油{あぶら}"]'::jsonb, 0, '化学的{かがくてき}な 処理{しょり}を せずに 実{み}を しぼった、いちばん 品質{ひんしつ}の 高{たか}い 油{あぶら}だよ。加熱{かねつ}より、そのまま かけて 香{かお}りを 楽{たの}しむのが おすすめだよ。', (select im.id from public.ingredients_master im where im.name = 'オリーブオイル' limit 1)),
  ('cooking', 'easy', '「米{こめ}」と いう 漢字{かんじ}を ばらすと、何{なん}と いう 数字{すうじ}に なる?', '["九十九{くじゅうく}","八十八{はちじゅうはち}","千{せん}","百{ひゃく}"]'::jsonb, 1, '米{こめ}の 字{じ}は 八{はち}・十{じゅう}・八{はち}に 分{わ}けられて、お米{こめ}が できるまでに 88回{かい}も 手間{てま}が かかると いわれているよ。', (select im.id from public.ingredients_master im where im.name = '米' limit 1)),
  ('cooking', 'normal', 'ココナッツミルクは、何{なに}から 作{つく}る?', '["ココヤシの 実{み}の 中{なか}の 水{みず}","ココヤシの 花{はな}","ココヤシの 実{み}の 白{しろ}い 果肉{かにく}","ココヤシの 葉{は}"]'::jsonb, 2, '熟{じゅく}した ココヤシの 白{しろ}い 果肉{かにく}を すりおろして、お水{みず}と 一緒{いっしょ}に しぼって 作{つく}るよ。', (select im.id from public.ingredients_master im where im.name = 'ココナッツミルク' limit 1)),
  ('cooking', 'easy', 'トマトは 太陽{たいよう}の 光{ひかり}を 浴{あ}びる 前{まえ}、何色{なにいろ}を しているかな?', '["緑色{みどりいろ}","黄色{きいろ}","紫色{むらさきいろ}"]'::jsonb, 0, 'はじめは みんな 緑色{みどりいろ}で、太陽{たいよう}の 光{ひかり}を 浴{あ}びる ほど だんだん 赤{あか}く 熟{じゅく}して いくよ。', (select im.id from public.ingredients_master im where im.name = 'トマト' limit 1)),
  ('cooking', 'easy', '苺{いちご}の まわりに ある「粒々{つぶつぶ}」の 正体{しょうたい}は なにかな?', '["種{たね}","花弁{はなびら}","金糸{きんし}"]'::jsonb, 0, 'あの 粒々{つぶつぶ} ひとつ ひとつが 苺{いちご}の 果実{かじつ}で、その 中{なか}に 本当{ほんとう}の 種{たね}が 入{はい}っているよ。', null),
  ('cooking', 'easy', '鮭{さけ}の 身{み}は 綺麗{きれい}な ピンク色{いろ}を しているが、実際{じっさい}は 何{なに}に 分類{ぶんるい}されるかな?', '["白身魚{しろみざかな}","赤身魚{あかみざかな}","青魚{あおざかな}"]'::jsonb, 0, '色{いろ}は ピンクだけど、生{う}まれた ときは 白身{しろみ}の 魚{さかな}だよ。食{た}べている エサに 含{ふく}まれる 色素{しきそ}が 体{からだ}に たまって ピンク色{いろ}に なるんだ。', null),
  ('cooking', 'easy', 'お寿司{すし}に 使{つか}われる「ガリ(生姜{しょうが}の 甘酢漬{あまずづ}け)」は、なぜ 食{た}べるのかな?', '["口{くち}の 中{なか}を さっぱりさせるため","お腹{なか}を いっぱいにするため","魚{さかな}の 骨{ほね}を 取{と}るため"]'::jsonb, 0, '次{つぎ}の ネタを 美味{おい}しく 味{あじ}わえる ように、口{くち}の 中{なか}を さっぱり リセットする 役割{やくわり}が あるよ。', (select im.id from public.ingredients_master im where im.name = 'しょうが' limit 1)),
  ('cooking', 'normal', 'ピーマンを 切{き}った ときに 見{み}える 中{なか}の「種{たね}」、実際{じっさい}は どうするのが 正解{せいかい}?', '["捨{す}てずに 食{た}べられる","必{かなら}ず きれいに 取{と}り除{のぞ}く","水{みず}で 洗{あら}ってから 乾{かわ}かす"]'::jsonb, 0, '種{たね}や わたにも 栄養{えいよう}が あって、じつは 食{た}べられるよ。細{こま}かく 刻{きざ}んで 一緒{いっしょ}に 料理{りょうり}しても いいよ。', (select im.id from public.ingredients_master im where im.name = 'ピーマン' limit 1)),
  ('cooking', 'normal', '玉葱{たまねぎ}を 切{き}ると 涙{なみだ}が 出{で}る 原因{げんいん}に なる 成分{せいぶん}は、どの グループの ものかな?', '["硫化{いおうか}アリル(硫黄{いおう}の 仲間{なかま})","カプサイシン","クエン酸{さん}"]'::jsonb, 0, '玉葱{たまねぎ}を 切{き}ると、硫黄{いおう}を 含{ふく}む 成分{せいぶん}が 空気中{くうきちゅう}に 飛{と}び散{ち}って 目{め}を 刺激{しげき}するよ。にんにくの 匂{にお}いの もとに なる 成分{せいぶん}とは 少{すこ}し 違{ちが}う 仲間{なかま}だよ。', (select im.id from public.ingredients_master im where im.name = '玉ねぎ' limit 1)),
  ('storage', 'hard', 'じゃがいもの 芽{め}や、緑色{みどりいろ}に なった 皮{かわ}に 含{ふく}まれ、食{た}べると お腹{なか}を こわす 毒{どく}の 成分{せいぶん}の 名前{なまえ}は?', '["ソラニン","カフェイン","タンニン"]'::jsonb, 0, '日光{にっこう}に 当{あ}たると 増{ふ}える 毒{どく}の 成分{せいぶん}だよ。食{た}べる ときは 芽{め}と 緑色{みどりいろ}の 部分{ぶぶん}を しっかり 取{と}り除{のぞ}いてね。', (select im.id from public.ingredients_master im where im.name = 'じゃがいも' limit 1)),
  ('cooking', 'easy', '日本{にほん}で いちばん 多{おお}く 作{つく}られている お米{こめ}の 品種{ひんしゅ}の 名前{なまえ}は どれかな?', '["コシヒカリ","あきたこまち","ひとめぼれ"]'::jsonb, 0, 'コシヒカリは 長{なが}い あいだ、作付面積{さくつけめんせき}も 収穫量{しゅうかくりょう}も 日本一{にほんいち}を 誇{ほこ}る 品種{ひんしゅ}だよ。', (select im.id from public.ingredients_master im where im.name = '米' limit 1)),
  ('cooking', 'normal', '生卵{なまたまご}の 黄身{きみ}の 色{いろ}が 濃{こ}い オレンジ色{いろ}なのは、どうしてかな?', '["栄養{えいよう}が たくさん あるから","餌{えさ}の 色{いろ}が 反映{はんえい}されているから","鶏{にわとり}が 年{とし}を とっているから"]'::jsonb, 1, '鶏{にわとり}が 食{た}べる 餌{えさ}に 含{ふく}まれる 色素{しきそ}の 量{りょう}で 黄身{きみ}の 色{いろ}の 濃{こ}さが 変{か}わるよ。色{いろ}の 濃{こ}さと 栄養{えいよう}の 量{りょう}は 直接{ちょくせつ} 関係{かんけい}ないよ。', (select im.id from public.ingredients_master im where im.name = '卵' limit 1)),
  ('cooking', 'easy', '人参{にんじん}は、植物{しょくぶつ}の どの 部分{ぶぶん}を 食{た}べているかな?', '["根{ね}っこ","葉{は}っぱ","茎{くき}"]'::jsonb, 0, '土{つち}の 中{なか}で 太{ふと}く なった 根{ね}っこの 部分{ぶぶん}を 食{た}べているよ。', (select im.id from public.ingredients_master im where im.name = '人参' limit 1)),
  ('cooking', 'normal', 'ブロッコリーの 私{わたし}たちが 食{た}べている 部分{ぶぶん}は、植物{しょくぶつ}の どの 部分{ぶぶん}かな?', '["つぼみの 集{あつ}まり","実{み}の 部分{ぶぶん}","葉{は}っぱ"]'::jsonb, 0, 'あの 小{ちい}さな つぶつぶは、まだ 花{はな}が 咲{さ}く 前{まえ}の つぼみが たくさん 集{あつ}まった ものだよ。', (select im.id from public.ingredients_master im where im.name = 'ブロッコリー' limit 1)),
  ('cooking', 'normal', 'バナナは 木{き}に 生{な}っている? それとも 何{なに}に 生{な}っているかな?', '["木{き}","草{くさ}","蔓{つる}"]'::jsonb, 1, 'バナナの 木{き}に 見{み}える ものは、じつは 葉{は}っぱが 重{かさ}なって できた 大{おお}きな 草{くさ}だよ。だから 分類{ぶんるい}では 草{くさ}に なるんだ。', (select im.id from public.ingredients_master im where im.name = 'バナナ' limit 1)),
  ('cooking', 'hard', '西瓜{すいか}は 野菜{やさい}と 果物{くだもの}の どちらに 分類{ぶんるい}されることが 多{おお}いかな?', '["野菜{やさい}(青果物{せいかぶつ}としての 分類{ぶんるい})","果物{くだもの}","木{き}の実{み}"]'::jsonb, 0, '畑{はたけ}で 育{そだ}つ 草{くさ}の 仲間{なかま}なので、農業{のうぎょう}の 統計{とうけい}などでは 野菜{やさい}として 扱{あつか}われる ことが 多{おお}いよ。甘{あま}いから 果物{くだもの}売{う}り場{ば}に 並{なら}ぶ ことも 多{おお}いよ。', null),
  ('cooking', 'normal', '鮪{まぐろ}は 泳{およ}ぎ続{つづ}ける ことを やめると、どうなって しまうかな?', '["溺{おぼ}れて(窒息{ちっそく}して) 死{し}んでしまう","眠{ねむ}ってしまう","地面{じめん}に 落{お}ちる"]'::jsonb, 0, '口{くち}を 開{あ}けて 泳{およ}ぎながら エラに 水{みず}を 通{とお}し 続{つづ}けないと 呼吸{こきゅう}が できない 仲間{なかま}だからだよ。', (select im.id from public.ingredients_master im where im.name = '本マグロ（大トロ）' limit 1)),
  ('cooking', 'normal', 'お味噌{みそ}の 原料{げんりょう}は 大豆{だいず}だが、そこに 混{ま}ぜる「麹{こうじ}」の 種類{しゅるい}は 何{なん}と 何{なん}が 主流{しゅりゅう}かな?', '["米{こめ}・麦{むぎ}・豆{まめ}","麦{むぎ}・とうもろこし・蕎麦{そば}","米{こめ}・粟{あわ}・稗{ひえ}"]'::jsonb, 0, '地域{ちいき}や 好{この}みに よって、米味噌{こめみそ}・麦味噌{むぎみそ}・豆味噌{まめみそ}などが 使{つか}い分{わ}けられているよ。', (select im.id from public.ingredients_master im where im.name = 'みそ' limit 1)),
  ('cooking', 'easy', '牛乳{ぎゅうにゅう}パックに 描{えが}かれている「切欠{きりか}き(小{ちい}さな へこみ)」は、何{なん}の 目印{めじるし}かな?', '["目{め}の 不自由{ふじゆう}な 人{ひと}のための 目印{めじるし}","牛乳{ぎゅうにゅう}が 新鮮{しんせん}な 目印{めじるし}","リサイクルできる 目印{めじるし}"]'::jsonb, 0, 'パックの 反対側{はんたいがわ}の 開{あ}け口{ぐち}が すぐ わかる ように、上{うえ}の ほうに つけられた 目印{めじるし}だよ。', (select im.id from public.ingredients_master im where im.name = '牛乳' limit 1)),
  ('cooking', 'normal', 'パイナップルは、どうやって 育{そだ}つかな?', '["地上{ちじょう}の 低{ひく}い 草{くさ}の 真{ま}ん中{なか}に 1個{こ}できる","大{おお}きな 木{き}に たくさん ぶら下{さ}がる","土{つち}の 中{なか}で じゃがいもの ように 育{そだ}つ"]'::jsonb, 0, '背{せ}の 低{ひく}い 草{くさ}の 株{かぶ}の 真{ま}ん中{なか}に、上{うえ}向{む}きに 1個{こ}だけ 実{み}を つけるよ。', null),
  ('cooking', 'normal', 'カレーの ルーに とろみを つける 主{おも}な 材料{ざいりょう}は 何{なん}かな?', '["小麦粉{こむぎこ}","砂糖{さとう}","片栗粉{かたくりこ}"]'::jsonb, 0, '小麦粉{こむぎこ}と 油{あぶら}を 炒{いた}めて、ルーの ベースと とろみを 作{つく}っているよ。', null),
  ('cooking', 'hard', '鰹{かつお}の「初鰹{はつがつお}」と「戻{もど}り鰹{がつお}」、脂{あぶら}が のっていて 美味{おい}しいのは どっちかな?', '["戻{もど}り鰹{がつお}(秋{あき})","初鰹{はつがつお}(春{はる})","どちらも 同{おな}じ"]'::jsonb, 0, 'エサを たっぷり 食{た}べた 秋{あき}の 戻{もど}り鰹{がつお}は 脂{あぶら}が のって 濃厚{のうこう}な 味{あじ}わいに なるよ。春{はる}の 初鰹{はつがつお}は あっさりした 味{あじ}わいだよ。', (select im.id from public.ingredients_master im where im.name = '初ガツオ' limit 1)),
  ('cooking', 'easy', '唐黍{とうもろこし}の 粒{つぶ}の 数{かず}は、どんな 数{かず}に なっているかな?', '["必{かなら}ず「偶数{ぐうすう}」","必{かなら}ず「奇数{きすう}」","ばらばらで 決{き}まっていない"]'::jsonb, 0, '花{はな}の 仕組{しく}みに 合{あ}わせて 育{そだ}つ ので、粒{つぶ}の 数{かず}は だいたい 偶数{ぐうすう}に なると いわれているよ。', null),
  ('cooking', 'normal', 'キャベツの「外側{そとがわ}の 緑{みどり}の 葉{は}」と「内側{うちがわ}の 白{しろ}い 葉{は}」、甘{あま}みが 強{つよ}いのは どっちかな?', '["内側{うちがわ}の 白{しろ}い 葉{は}","外側{そとがわ}の 緑{みどり}の 葉{は}","どちらも 同{おな}じ"]'::jsonb, 0, '日光{にっこう}が 当{あ}たりにくい 内側{うちがわ}の 葉{は}は、栄養{えいよう}を たくわえていて 甘{あま}みが 強{つよ}く なるよ。', (select im.id from public.ingredients_master im where im.name = 'キャベツ' limit 1)),
  ('cooking', 'easy', '鶏{にわとり}の 卵{たまご}の 殻{から}の 色{いろ}(白{しろ}と 赤{あか}・茶色{ちゃいろ})、栄養{えいよう}に 違{ちが}いは あるかな?', '["栄養{えいよう}は 同{おな}じ","赤{あか}い 卵{たまご}の ほうに 栄養{えいよう}が ある","白{しろ}い 卵{たまご}の ほうに 栄養{えいよう}が ある"]'::jsonb, 0, '殻{から}の 色{いろ}は 鶏{にわとり}の 種類{しゅるい}(品種{ひんしゅ})で 決{き}まる もので、中身{なかみ}の 栄養{えいよう}には 差{さ}が ないよ。', (select im.id from public.ingredients_master im where im.name = '卵' limit 1)),
  ('cooking', 'normal', '「醤油{しょうゆ}」の 原料{げんりょう}に 含{ふく}まれていない ものは 次{つぎ}の うち どれかな?', '["牛乳{ぎゅうにゅう}","大豆{だいず}","小麦{こむぎ}"]'::jsonb, 0, '醤油{しょうゆ}は 大豆{だいず}・小麦{こむぎ}・塩{しお}・麹{こうじ}から 作{つく}られるよ。牛乳{ぎゅうにゅう}は 使{つか}わないよ。', null),
  ('cooking', 'hard', '蓮根{れんこん}に 穴{あな}が 開{あ}いているのは、何{なん}の ため?', '["空気{くうき}を 根{ね}まで 届{とど}ける ため","水抜{みずぬ}きを する ため","魚{さかな}が 通{とお}り抜{ぬ}ける ため"]'::jsonb, 0, '酸素{さんそ}の 少{すく}ない 泥{どろ}の 中{なか}でも 呼吸{こきゅう}できる ように、茎{くき}の 穴{あな}を 通{とお}して 空気{くうき}を 送{おく}っているよ。', (select im.id from public.ingredients_master im where im.name = 'れんこん' limit 1)),
  ('cooking', 'normal', '蛸{たこ}に 心臓{しんぞう}は いくつ あるかな?', '["3つ","1つ","5つ"]'::jsonb, 0, '体{からだ}の すみずみまで 血{ち}を 送{おく}る ために、心臓{しんぞう}が 全部{ぜんぶ}で 3つ あるよ。', (select im.id from public.ingredients_master im where im.name = 'たこ' limit 1)),
  ('cooking', 'easy', '西瓜{すいか}の 縞模様{しまもよう}は、何{なん}の ために あると いわれているかな?', '["保護色{ほごしょく}(敵{てき}から 身{み}を 守{まも}る ため)","太陽{たいよう}の 光{ひかり}を 集{あつ}める ため","水分{すいぶん}を 逃{に}がさない ため"]'::jsonb, 0, '野生{やせい}の 動物{どうぶつ}などから 見{み}つかりにくく する カモフラージュの 役割{やくわり}ではないかと 考{かんが}えられているよ。', null),
  ('cooking', 'normal', 'お肉{にく}を 料理{りょうり}する 前{まえ}に「ワイン」や「ヨーグルト」に 漬{つ}けると、どうなるかな?', '["お肉{にく}が 柔{やわ}らかく なる","お肉{にく}の 色{いろ}が 真{ま}っ白{しろ}に なる","お肉{にく}の 量{りょう}が 増{ふ}える"]'::jsonb, 0, '酸{さん}の 働{はたら}きで 筋{すじ}の 繊維{せんい}が ほぐれて、焼{や}いても 柔{やわ}らかく ジューシーに なるよ。', null),
  ('cooking', 'easy', '薩摩芋{さつまいも}は、植物{しょくぶつ}の どの 部分{ぶぶん}を 食{た}べているかな?', '["根{ね}っこ(芋{いも}の 部分{ぶぶん})","茎{くき}","葉{は}っぱ"]'::jsonb, 0, 'じゃがいもは 茎{くき}を 食{た}べているけど、薩摩芋{さつまいも}は 栄養{えいよう}を たくわえた 根{ね}っこの 部分{ぶぶん}を 食{た}べているよ。', (select im.id from public.ingredients_master im where im.name = 'さつまいも' limit 1)),
  ('cooking', 'normal', 'お米{こめ}を 研{と}ぐ(洗{あら}う) とき、最初{さいしょ}の 水{みず}は なぜ 素早{すばや}く 捨{す}てた ほうが いいのかな?', '["汚{よご}れや 匂{にお}いを 吸{す}い込{こ}みやすいから","お米{こめ}が 溶{と}けてしまうから","お米{こめ}が 冷{つめ}たくなりすぎるから"]'::jsonb, 0, '乾{かわ}いた お米{こめ}は 最初{さいしょ}の 水分{すいぶん}を 一気{いっき}に 吸{す}い込{こ}むから、その 水{みず}は 素早{すばや}く 捨{す}てるのが コツだよ。', (select im.id from public.ingredients_master im where im.name = '米' limit 1)),
  ('cooking', 'hard', 'アスパラガスの「グリーン」と「ホワイト」、品種{ひんしゅ}の 違{ちが}いは 何{なん}かな?', '["育{そだ}て方{かた}の 違{ちが}い(日光{にっこう}を 当{あ}てるか 当{あ}てないか)","元々{もともと}の 種類{しゅるい}の 違{ちが}い","収穫{しゅうかく}する 季節{きせつ}の 違{ちが}い"]'::jsonb, 0, '土{つち}を かぶせて 日光{にっこう}を さえぎり、緑色{みどりいろ}に させずに 育{そだ}てた ものが ホワイトアスパラガスだよ。', (select im.id from public.ingredients_master im where im.name = '初物アスパラガス' limit 1)),
  ('cooking', 'normal', '海老{えび}や 蟹{かに}は、茹{ゆ}でると どうして 赤{あか}くなるのかな?', '["中{なか}の 赤{あか}い 色素{しきそ}が 熱{ねつ}で 現{あらわ}れるから","血{ち}が 表面{ひょうめん}に 出{で}てくるから","火傷{やけど}して 赤{あか}くなっているから"]'::jsonb, 0, '熱{ねつ}に 強{つよ}い 赤{あか}い 色素{しきそ}(アスタキサンチン)が、たんぱくしつと 離{はな}れて 表面{ひょうめん}に 現{あらわ}れるからだよ。', (select im.id from public.ingredients_master im where im.name = 'えび' limit 1)),
  ('cooking', 'easy', 'キウイフルーツの 名前{なまえ}の 由来{ゆらい}に なった、ニュージーランドの「鳥{とり}」の 名前{なまえ}は?', '["キウイバード","コウモリ","ペンギン"]'::jsonb, 0, '羽{はね}の ない 丸{まる}っこい 姿{すがた}が 鳥{とり}の キウイに 似{に}ている ことから 名前{なまえ}が つけられたよ。', null),
  ('nutrition', 'normal', '豚肉{ぶたにく}に 含{ふく}まれていて、体{からだ}の 疲{つか}れを とる ビタミンとして 特{とく}に 有名{ゆうめい}な ものは どれかな?', '["ビタミンB1","ビタミンC","ビタミンD"]'::jsonb, 0, '糖質{とうしつ}を エネルギーに 変{か}える 働{はたら}きを 助{たす}けて、疲{つか}れを とるのに 役立{やくだ}つよ。', (select im.id from public.ingredients_master im where im.name = '豚ロース肉' limit 1)),
  ('cooking', 'normal', '南瓜{かぼちゃ}は、収穫{しゅうかく}したてよりも、少{すこ}し 時間{じかん}を 置{お}いてから 食{た}べた ほうが 美味{おい}しいのは なぜ?', '["甘{あま}みと 旨味{うまみ}が 増{ま}すから","水分{すいぶん}が 抜{ぬ}けて 軽{かる}くなるから","皮{かわ}が 柔{やわ}らかくなるから"]'::jsonb, 0, '少{すこ}し 寝{ね}かせる あいだに でんぷんが 糖{とう}に 変{か}わって、甘{あま}みが 増{ま}すよ。', (select im.id from public.ingredients_master im where im.name = 'かぼちゃ' limit 1)),
  ('cooking', 'hard', '「本味醂{ほんみりん}」と「発酵調味料{はっこうちょうみりょう}(みりん風{ふう}調味料{ちょうみりょう})」の 大{おお}きな 違{ちが}いは 何{なん}かな?', '["アルコールが 入{はい}っているかどうか","塩分{えんぶん}が 入{はい}っているかどうか","色{いろ}の 濃{こ}さ"]'::jsonb, 0, '本味醂{ほんみりん}は お酒{さけ}の 仲間{なかま}で アルコールを 含{ふく}むけど、みりん風{ふう}調味料{ちょうみりょう}は ほとんど 含{ふく}まないよ。', null),
  ('cooking', 'easy', 'お料理{りょうり}で「さ・し・す・せ・そ」の 順番{じゅんばん}で 調味料{ちょうみりょう}を 入{い}れると 良{よ}いと されているが、「す」は 何{なん}かな?', '["酢{す}","砂糖{さとう}","塩{しお}"]'::jsonb, 0, 'さ=砂糖{さとう}、し=塩{しお}、す=酢{す}、せ=醤油{しょうゆ}、そ=味噌{みそ}の 順番{じゅんばん}を 表{あらわ}しているよ。', null),
  ('cooking', 'normal', '胡瓜{きゅうり}の 切{き}り口{ぐち}を くるくる 合{あ}わせると 出{で}てくる「白{しろ}い 液体{えきたい}」、あれの 正体{しょうたい}は なにかな?', '["苦味{にがみ}の 成分{せいぶん}を 含{ふく}んだ 灰汁{あく}","砂糖{さとう}の 成分{せいぶん}","でんぷん"]'::jsonb, 0, '胡瓜{きゅうり}が 自分{じぶん}を 守{まも}る ための 苦味{にがみ}成分{せいぶん}だよ。切{き}り口{ぐち}を こすり合{あ}わせると 少{すこ}し 減{へ}らせると いわれているよ。', (select im.id from public.ingredients_master im where im.name = 'きゅうり' limit 1)),
  ('cooking', 'easy', 'ほうれん草{そう}は、茹{ゆ}でてから 水{みず}に さらす ことが 多{おお}いが、その 一番{いちばん}の 理由{りゆう}は どれかな?', '["灰汁{あく}(シュウ酸{さん})を 抜{ぬ}くため","冷{つめ}たくして シャキシャキにするため","綺麗{きれい}な 緑色{みどりいろ}を キープするため"]'::jsonb, 0, 'えぐみの 原因{げんいん}に なる シュウ酸{さん}を 水{みず}に 溶{と}かして 抜{ぬ}く ためだよ。', (select im.id from public.ingredients_master im where im.name = 'ほうれん草' limit 1)),
  ('cooking', 'normal', '日本{にほん}の 食卓{しょくたく}で おなじみの「シシャモ」、私{わたし}たちが 普段{ふだん} 食{た}べている ものの 実際{じっさい}の 正体{しょうたい}は 何{なん}と いう 魚{さかな}の 仲間{なかま}かな?', '["カペリン(代用{だいよう}の 魚{さかな})","本物{ほんもの}の シシャモ","イカナゴ"]'::jsonb, 0, 'お店{みせ}で 売{う}られている シシャモの 多{おお}くは、カペリンと いう 代{か}わりの 魚{さかな}だよ。本物{ほんもの}の シシャモは 北海道{ほっかいどう}で とれる めずらしい 魚{さかな}だよ。', null),
  ('cooking', 'hard', '西瓜{すいか}の 黒{くろ}い「種{たね}」、飲{の}み込{こ}んでしまうと どうなるかな?', '["お腹{なか}の 中{なか}で 芽{め}は 出{で}ない(消化{しょうか}される)","胃{い}の 中{なか}で 西瓜{すいか}が 育{そだ}ってしまう","お腹{なか}を こわしてしまう"]'::jsonb, 0, '種{たね}は 胃酸{いさん}で 消化{しょうか}されるから、飲{の}み込{こ}んでも 体{からだ}の 中{なか}で 芽{め}が 出{で}る ことは ないよ。', null),
  ('cooking', 'normal', 'ブロッコリーと 同{おな}じ アブラナ科{か}の 仲間{なかま}で、白{しろ}い 見{み}た目{め}の 野菜{やさい}と いえば どれかな?', '["カリフラワー","レタス","茄子{なす}"]'::jsonb, 0, 'ブロッコリーの 仲間{なかま}から 生{う}まれたと される、同{おな}じ つぼみを 食{た}べる 野菜{やさい}だよ。', null),
  ('cooking', 'easy', '鶏肉{とりにく}の 部位{ぶい}で「ささみ」と 呼{よ}ばれる 場所{ばしょ}は、鶏{にわとり}の 体{からだ}の どのあたりに あるかな?', '["胸{むね}の 内側{うちがわ}の 筋肉{きんにく}","手羽先{てばさき}の 先{さき}っぽ","腿{もも}の 裏側{うらがわ}"]'::jsonb, 0, '胸肉{むねにく}の 内側{うちがわ}に ある、脂{あぶら}が 少{すく}なくて ヘルシーな 部位{ぶい}だよ。', null),
  ('cooking', 'normal', '砂糖{さとう}の 原料{げんりょう}として、日本{にほん}で よく 使{つか}われている 2つの 植物{しょくぶつ}は 何{なん}かな? サトウキビと 何{なに}?', '["甜菜{てんさい}(ビート)","薩摩芋{さつまいも}","唐黍{とうもろこし}"]'::jsonb, 0, '南{みなみ}の サトウキビと、北{きた}の 甜菜{てんさい}(ビート)が 国内{こくない}の 主{おも}な 砂糖{さとう}の 原料{げんりょう}だよ。', null),
  ('storage', 'normal', 'お米{こめ}の 保存{ほぞん}で、いちばん 美味{おい}しい 状態{じょうたい}を キープできる 場所{ばしょ}は どこかな?', '["冷蔵庫{れいぞうこ}の 野菜室{やさいしつ}","キッチンの 棚{たな}","日{ひ}の 当{あ}たる 窓際{まどぎわ}"]'::jsonb, 0, '温度{おんど}と 湿度{しつど}が 安定{あんてい}している 冷蔵庫{れいぞうこ}の 野菜室{やさいしつ}が 保存{ほぞん}に ぴったりだよ。', (select im.id from public.ingredients_master im where im.name = '米' limit 1)),
  ('cooking', 'easy', '大根{だいこん}は、上{うえ}の ほう(葉{は}に 近{ちか}い 方{ほう})と 下{した}の ほう(先端{せんたん})、どちらが 辛味{からみ}が 強{つよ}いかな?', '["下{した}の ほう(先端{せんたん})","上{うえ}の ほう","どちらも 同{おな}じ"]'::jsonb, 0, '先端{せんたん}に いく ほど 辛{から}み成分{せいぶん}が 強{つよ}くなり、上{うえ}の ほうは 甘{あま}みが 強{つよ}いよ。', (select im.id from public.ingredients_master im where im.name = '大根' limit 1)),
  ('cooking', 'hard', 'お肉{にく}を 柔{やわ}らかくする ために、果物{くだもの}の 何{なに}を 入{い}れると 効果的{こうかてき}かな?', '["パイナップルや キウイ","林檎{りんご}や バナナ","レモンや オレンジ"]'::jsonb, 0, 'パイナップルや キウイには、たんぱくしつを 分解{ぶんかい}する 力{ちから}が あって、お肉{にく}を 柔{やわ}らかく 仕上{しあ}げてくれるよ。', null),
  ('cooking', 'normal', '貝類{かいるい}の「砂抜{すなぬ}き」、海水{かいすい}と 同{おな}じ 濃度{のうど}の 塩水{しおみず}(約{やく}何{なん}%)に すると 一番{いちばん} 元気{げんき}に 砂{すな}を 吐{は}くかな?', '["約{やく}3%","約{やく}10%","約{やく}0.5%"]'::jsonb, 0, '海{うみ}と 同{おな}じ くらいの 塩分{えんぶん}濃度{のうど}に すると、貝{かい}が 安心{あんしん}して 元気{げんき}に 砂{すな}を 吐{は}いてくれるよ。', null),
  ('cooking', 'normal', '唐黍{とうもろこし}は、収穫{しゅうかく}してから 時間{じかん}が 経{た}つと どうなってしまうかな?', '["甘{あま}みが どんどん 減{へ}ってしまう","どんどん 甘{あま}くなる","味{あじ}が 酸{す}っぱくなる"]'::jsonb, 0, '収穫後{しゅうかくご}から 糖分{とうぶん}が でんぷんに 変{か}わって いくから、もぎたてが いちばん 甘{あま}いよ。', null),
  ('cooking', 'normal', '蜜柑{みかん}の 皮{かわ}を むいた ときに 見{み}える、白{しろ}い 筋{すじ}(繊維{せんい})の ことを 何{なん}と 呼{よ}ぶかな?', '["アルベド","雲綿{くもわた}","柑橘筋{かんきつすじ}"]'::jsonb, 0, 'アルベドと 呼{よ}ばれる 部分{ぶぶん}だよ。ビタミンPなどが 含{ふく}まれていて、そのまま 食{た}べても 体{からだ}に いいよ。', (select im.id from public.ingredients_master im where im.name = 'みかん' limit 1)),
  ('cooking', 'hard', '茄子{なす}を 炒{いた}めたり 揚{あ}げたりすると、綺麗{きれい}な 紫色{むらさきいろ}や トロッとした 食感{しょっかん}に なる 理由{りゆう}は どれかな?', '["油{あぶら}が 回{まわ}って 色{いろ}が キープされ、スポンジ状{じょう}の 組織{そしき}に 油{あぶら}が 染{し}み込{こ}むから","水{みず}に 溶{と}けて 消{き}えるから","空気{くうき}と 混{ま}ざって 固{かた}くなるから"]'::jsonb, 0, '茄子{なす}の 皮{かわ}の 紫色{むらさきいろ}の 色素{しきそ}は 油{あぶら}で 守{まも}られて、実{み}の スポンジのような 組織{そしき}に 油{あぶら}が しみこんで トロッと するよ。', (select im.id from public.ingredients_master im where im.name = 'ナス' limit 1)),
  ('cooking', 'normal', '茹{ゆ}で卵{たまご}を 作{つく}った あとに「すぐ 冷{つめ}たい 水{みず}(氷水{こおりみず})に つける」と、どんな 良{よ}い ことが あるかな?', '["殻{から}が ツルッと 剥{む}きやすくなる","黄身{きみ}が 真{ま}ん中{なか}に くる","卵{たまご}が 長持{ながも}ちする"]'::jsonb, 0, '急{きゅう}に 冷{ひ}やす ことで 白身{しろみ}が 縮{ちぢ}んで、殻{から}との あいだに 隙間{すきま}が できるから 剥{む}きやすく なるよ。', (select im.id from public.ingredients_master im where im.name = '卵' limit 1)),
  ('cooking', 'easy', '醤油{しょうゆ}の ボトルに「開栓後要冷蔵{かいせんごようれいぞう}」と 書{か}いてある ことが 多{おお}いのは なぜ?', '["空気{くうき}に 触{ふ}れると 味{あじ}が 落{お}ちたり 傷{いた}んだりするから","凍{こお}ってしまうから","色{いろ}が 透明{とうめい}になってしまうから"]'::jsonb, 0, '開{あ}けた あとは 空気{くうき}に 触{ふ}れて 酸化{さんか}が 進{すす}みやすいから、風味{ふうみ}を 守{まも}る ために 冷蔵庫{れいぞうこ}で 保存{ほぞん}するんだよ。', null),
  ('storage', 'easy', 'トマトの ヘタを 上{うえ}にして 保存{ほぞん}するよりも、ヘタを 下{した}(逆{さか}さ)にして 保存{ほぞん}した ほうが いい 理由{りゆう}は?', '["ヘタの 穴{あな}から 水分{すいぶん}が 逃{に}げるのを 防{ふせ}げるから","転{ころ}がらないように する ため","赤{あか}くなりやすいため"]'::jsonb, 0, 'いちばん 傷{いた}みやすい ヘタの まわりを 下{した}向{む}きに する ことで、水分{すいぶん}が 逃{に}げにくく なって 長持{ながも}ちするよ。', (select im.id from public.ingredients_master im where im.name = 'トマト' limit 1)),
  ('cooking', 'normal', '揚{あ}げ物{もの}を する ときに「一度{いちど}に たくさんの 材料{ざいりょう}を 入{い}れると カラッと 揚{あ}がらない」のは なぜ?', '["油{あぶら}の 温度{おんど}が 下{さ}がってしまうから","鍋{なべ}が あふれてしまうから","油{あぶら}が 綺麗{きれい}になるから"]'::jsonb, 0, '冷{つめ}たい 材料{ざいりょう}を 一度{いちど}に たくさん 入{い}れると 油{あぶら}の 温度{おんど}が 急{きゅう}に 下{さ}がって、衣{ころも}が 油{あぶら}を 吸{す}って べたつく 原因{げんいん}に なるよ。', null),
  ('storage', 'easy', '炊{た}きたての ごはんを 美味{おい}しく 保存{ほぞん}する ために、一番{いちばん} 適{てき}している 方法{ほうほう}は どれかな?', '["熱{あつ}いうちに ラップに 包{つつ}んで 冷凍{れいとう}する","冷蔵庫{れいぞうこ}で そのまま 冷{ひ}やす","炊飯器{すいはんき}の 中{なか}で 保温{ほおん}し続{つづ}ける"]'::jsonb, 0, '美味{おい}しさと 水分{すいぶん}を 閉{と}じ込{こ}める ために、熱{あつ}いうちに ラップで 包{つつ}んで 冷凍{れいとう}するのが いちばん おすすめだよ。', (select im.id from public.ingredients_master im where im.name = '米' limit 1)),
  ('cooking', 'hard', '蟹{かに}の 身{み}を 上手{じょうず}に スポッと 抜{ぬ}き出{だ}す ために、プロが よく 使{つか}う 裏技{うらわざ}は どれかな?', '["殻{から}の 関節{かんせつ}の 少{すこ}し 上{うえ}を ハサミで 切{き}る","お湯{ゆ}に 塩{しお}を 入{い}れる","冷凍庫{れいとうこ}で 一晩{ひとばん} 凍{こお}らせる"]'::jsonb, 0, '関節{かんせつ}の 近{ちか}くを 切{き}る ことで、中{なか}の 身{み}が つながった まま スルッと 取{と}り出{だ}せるよ。', (select im.id from public.ingredients_master im where im.name = 'ズワイガニ' limit 1)),
  ('storage', 'normal', 'じゃがいもの 芽{め}が 出{で}ないように する ため、一緒{いっしょ}に 袋{ふくろ}に 入{い}れて おくと 良{よ}いと される 野菜{やさい}や 果物{くだもの}は?', '["林檎{りんご}","人参{にんじん}","玉葱{たまねぎ}"]'::jsonb, 0, '林檎{りんご}から 出{で}る ガスが、じゃがいもの 芽{め}が 出{で}るのを 抑{おさ}えてくれると いわれているよ。', (select im.id from public.ingredients_master im where im.name = 'じゃがいも' limit 1)),
  ('cooking', 'easy', '牛肉{ぎゅうにく}の ステーキを 焼{や}く 直前{ちょくぜん}、冷蔵庫{れいぞうこ}から 出{だ}して すぐ 焼{や}くよりも、どうしてから 焼{や}いた ほうが 美味{おい}しく 焼{や}けるかな?', '["常温{じょうおん}に 戻{もど}してから 焼{や}く","水{みず}で 洗{あら}ってから 焼{や}く","レンジで 温{あたた}めてから 焼{や}く"]'::jsonb, 0, '中心{ちゅうしん}が 冷{つめ}たい ままだと 外側{そとがわ}だけ 焦{こ}げてしまうから、常温{じょうおん}に 戻{もど}して 均一{きんいつ}に 火{ひ}を 通{とお}すと いいと いわれているよ。', null),
  ('cooking', 'normal', 'バナナに できる「黒{くろ}い 斑点{はんてん}」の 名前{なまえ}を なんと 言{い}うかな?', '["シュガースポット","ブラックスポット","スウィートドット"]'::jsonb, 0, '糖度{とうど}が 上{あ}がって 熟{じゅく}してきた サインで、いちばん 甘{あま}みを 感{かん}じられる 状態{じょうたい}だよ。', (select im.id from public.ingredients_master im where im.name = 'バナナ' limit 1)),
  ('cooking', 'hard', 'ニンニクの 芽{め}と 呼{よ}ばれる 部分{ぶぶん}は、植物{しょくぶつ}の 成長{せいちょう}に おいて 正確{せいかく}には どの 部分{ぶぶん}に 当{あ}たるかな?', '["花茎{かけい}(花{はな}が 咲{さ}くための 茎{くき})","根{ね}っこ","葉{は}っぱの 芯{しん}"]'::jsonb, 0, 'にんにくの 花{はな}を 咲{さ}かせる ための 茎{くき}の 部分{ぶぶん}だよ。早{はや}めに 摘{つ}み取{と}ると、球{たま}の 部分{ぶぶん}が 美味{おい}しく 育{そだ}つよ。', (select im.id from public.ingredients_master im where im.name = 'にんにく' limit 1));
